  return new Promise((resolve, reject) => {
    const onError = (error: unknown) => {
      if (getErrnoCode(error) === 'EADDRINUSE') resolve(false)
      else reject(error)
    }
    server.once('error', onError)
    server.listen(path, () => {
      server.removeListener('error', onError)
      resolve(true)
    })
  })
